from typing import List
import heapq

class Solution:
    def countMentions(self, numberOfUsers: int, events: List[List[str]]) -> List[int]:
        # Parse events into a list of (timestamp, type, data)
        parsed = []
        for e in events:
            typ = e[0]
            ts = int(e[1])
            if typ == "OFFLINE":
                uid = int(e[2])
                parsed.append((ts, typ, uid))
            else:  # MESSAGE
                parsed.append((ts, typ, e[2]))

        # Sort by timestamp, OFFLINE before MESSAGE at the same timestamp
        priority = {"OFFLINE": 0, "MESSAGE": 1}
        parsed.sort(key=lambda x: (x[0], priority[x[1]]))

        online = [True] * numberOfUsers  # all users start online
        mentions = [0] * numberOfUsers
        heap = []  # min‑heap for scheduled re‑online events (time, user)

        for ts, typ, data in parsed:
            # Bring users back online if their offline period ended
            while heap and heap[0][0] <= ts:
                _, uid = heapq.heappop(heap)
                online[uid] = True

            if typ == "OFFLINE":
                uid = data
                online[uid] = False
                heapq.heappush(heap, (ts + 60, uid))
            else:  # MESSAGE
                s = data
                if s == "ALL":
                    for i in range(numberOfUsers):
                        mentions[i] += 1
                elif s == "HERE":
                    for i in range(numberOfUsers):
                        if online[i]:
                            mentions[i] += 1
                else:
                    for tok in s.split():
                        if tok.startswith("id"):
                            try:
                                uid = int(tok[2:])
                            except ValueError:
                                continue
                            if 0 <= uid < numberOfUsers:
                                mentions[uid] += 1

        return mentions
