import sys, math, itertools

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    N, M = map(int, data)
    max_B = M - (N - 1) * 10

    # combinatorial count
    def comb(n, k):
        if k < 0 or k > n:
            return 0
        if k > n - k:
            k = n - k
        res = 1
        for i in range(1, k + 1):
            res = res * (n - k + i) // i
        return res

    try:
        count = math.comb(max_B + N - 1, N)
    except AttributeError:
        count = comb(max_B + N - 1, N)

    # Output count
    sys.stdout.write(str(count) + '\n')

    for B in itertools.combinations_with_replacement(range(1, max_B + 1), N):
        line = ' '.join(str(b + i * 10) for i, b in enumerate(B))
        sys.stdout.write(line + '\n')

if __name__ == "__main__":
    solve()
